1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <title>Pulsing Circle</title>
7	  <style>
8	    * {
9	      margin: 0;
10	      padding: 0;
11	      box-sizing: border-box;
12	    }
13	    body {
14	      width: 100vw;
15	      height: 100vh;
16	      display: flex;
17	      justify-content: center;
18	      align-items: center;
19	      background: radial-gradient(circle at center, #1a1a2e 0%, #0d0d17 100%);
20	      overflow: hidden;
21	    }
22	    svg {
23	      width: min(400px, 80vmin);
24	      height: min(400px, 80vmin);
25	      overflow: visible;
26	    }
27	    .core {
28	      animation: pulse 2.5s cubic-bezier(0.4, 0, 0.2, 1) infinite;
29	      transform-origin: 200px 200px;
30	      filter: url(#glow);
31	      will-change: transform, opacity;
32	    }
33	    .ring {
34	      fill: none;
35	      stroke: #8ec5ff;
36	      stroke-width: 2;
37	      transform-origin: 200px 200px;
38	      animation: ripple 2.5s ease-out infinite;
39	      will-change: transform, opacity;
40	    }
41	    .ring--delay-1 {
42	      animation-delay: 0.83s;
43	    }
44	    .ring--delay-2 {
45	      animation-delay: 1.66s;
46	    }
47	    @keyframes pulse {
48	      0%, 100% {
49	        transform: scale(1);
50	        opacity: 0.9;
51	      }
52	      50% {
53	        transform: scale(1.05);
54	        opacity: 1;
55	      }
56	    }
57	    @keyframes ripple {
58	      0% {
59	        transform: scale(1);
60	        opacity: 0.6;
61	      }
62	      100% {
63	        transform: scale(1.35);
64	        opacity: 0;
65	      }
66	    }
67	    @media (prefers-reduced-motion: reduce) {
68	      .core, .ring {
69	        animation: none;
70	      }
71	      .ring {
72	        opacity: 0.35;
73	      }
74	    }
75	  </style>
76	</head>
77	<body>
78	  <svg id="ae683f770" viewBox="0 0 400 400" role="img" aria-label="Pulsing blue circle animation">
79	    <defs>
80	      <radialGradient id="circleGradient" cx="35%" cy="35%" r="65%">
81	        <stop offset="0%" stop-color="#8ec5ff"/>
82	        <stop offset="55%" stop-color="#4a7dd9"/>
83	        <stop offset="100%" stop-color="#1f3a75"/>
84	      </radialGradient>
85	      <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
86	        <feGaussianBlur in="SourceGraphic" stdDeviation="8" result="blur"/>
87	        <feMerge>
88	          <feMergeNode in="blur"/>
89	          <feMergeNode in="SourceGraphic"/>
90	        </feMerge>
91	      </filter>
92	    </defs>
93	    <circle class="ring" cx="200" cy="200" r="180"/>
94	    <circle class="ring ring--delay-1" cx="200" cy="200" r="180"/>
95	    <circle class="ring ring--delay-2" cx="200" cy="200" r="180"/>
96	    <circle class="core" cx="200" cy="200" r="180" fill="url(#circleGradient)"/>
97	  </svg>
98	</body>
99	</html>
